19: #include "stdlib/complex/float32/ctor.h"
20: #include <stdint.h>
21: 
22: /**
23: * Returns a single-precision complex floating-point number.
24: *
25: * @param real     real component
26: * @param imag     imaginary component
27: * @return         single-precision complex floating-point number
28: *
29: * @example
30: * stdlib_complex64_t z = stdlib_complex64( 5.0f, 2.0f );
31: */
32: stdlib_complex64_t stdlib_complex64( const float real, const float imag ) {
33: 	stdlib_complex64_parts_t z;
34: 	z.parts[ 0 ] = real;
35: 	z.parts[ 1 ] = imag; // cppcheck-suppress unreadVariable
36: 	return z.value;
37: }
38: 
39: /**
40: * Converts a single-precision floating-point number to a single-precision complex floating-point number.
41: *
42: * @param real    real component
43: * @return        single-precision complex floating-point number
44: *
45: * @example
46: * stdlib_complex64_t z = stdlib_complex64_from_float32( 5.0f );
47: */
48: stdlib_complex64_t stdlib_complex64_from_float32( const float real ) {
49: 	stdlib_complex64_parts_t z;
50: 	z.parts[ 0 ] = real;
51: 	z.parts[ 1 ] = 0.0f; // cppcheck-suppress unreadVariable
52: 	return z.value;
53: }
54: 
55: /**
56: * Converts a double-precision floating-point number to a single-precision complex floating-point number.
57: *
58: * @param real    real component
59: * @return        single-precision complex floating-point number
60: *
61: * @example
62: * stdlib_complex64_t z = stdlib_complex64_from_float64( 5.0 );
63: */
64: stdlib_complex64_t stdlib_complex64_from_float64( const double real ) {
65: 	stdlib_complex64_parts_t z;
66: 	z.parts[ 0 ] = (float)real;
67: 	z.parts[ 1 ] = 0.0f; // cppcheck-suppress unreadVariable
68: 	return z.value;
69: }
70: 
71: /**
72: * Converts (copies) a single-precision complex floating-point number to a single-precision complex floating-point number.
73: *
74: * @param z       single-precision complex floating-point number
75: * @return        single-precision complex floating-point number
76: *
77: * @example
78: * stdlib_complex64_t z1 = stdlib_complex64( 5.0f, 3.0f );
79: * stdlib_complex64_t z2 = stdlib_complex64_from_complex64( z1 );
80: */
81: stdlib_complex64_t stdlib_complex64_from_complex64( const stdlib_complex64_t z ) {
82: 	stdlib_complex64_parts_t v1 = { z };
83: 	stdlib_complex64_parts_t v2;
84: 	v2.parts[ 0 ] = v1.parts[ 0 ];
85: 	v2.parts[ 1 ] = v1.parts[ 1 ]; // cppcheck-suppress unreadVariable
86: 	return v2.value;
87: }
88: 
89: /**
90: * Converts a signed 8-bit integer to a single-precision complex floating-point number.
91: *
92: * @param real    real component
93: * @return        single-precision complex floating-point number
94: *
95: * @example
96: * stdlib_complex64_t z = stdlib_complex64_from_int8( 5 );
97: */
98: stdlib_complex64_t stdlib_complex64_from_int8( const int8_t real ) {
99: 	stdlib_complex64_parts_t z;
100: 	z.parts[ 0 ] = (float)real;
101: 	z.parts[ 1 ] = 0.0f; // cppcheck-suppress unreadVariable
102: 	return z.value;
103: }
104: 
105: /**
106: * Converts an unsigned 8-bit integer to a single-precision complex floating-point number.
107: *
108: * @param real    real component
109: * @return        single-precision complex floating-point number
110: *
111: * @example
112: * stdlib_complex64_t z = stdlib_complex64_from_uint8( 5 );
